import { Mesh, Group, PlaneGeometry, Vector2 } from 'three/webgpu';
import { texture, uv } from 'three/tsl';
import { gsap } from 'gsap';
import { /* no primitives needed */ } from '@/primitives';
import { /* no text needed */ } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Object} [intent]
 * @property {Object} [visualSpec]
 * @property {Object} [visualSpec.colors]
 * @property {Array} [textContent]
 * @property {Array} [cinematicPrimitives]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {Object} textureLoader
 * @property {Function} emit
 * @property {Object} primitives
 * @property {Object} fontAtlas
 * @property {string} tier
 */

export default function createNode(config, ctx) {
  const { Group: THREEGroup, Mesh: THREEMesh, PlaneGeometry: THREEPlaneGeometry } = ctx.THREE;

  // Root container – the adapter will position/rotate/scale it.
  const root = new THREEGroup();

  // ---- Geometry -------------------------------------------------
  // Atlas region (0,0,512,320) – use its aspect ratio.
  const regionWidth = 512;
  const regionHeight = 320;
  const aspect = regionWidth / regionHeight;

  const geometry = new PlaneGeometry(aspect, 1, 1, 1);
  // Adjust UVs so that only the specified region is sampled.
  // Assuming the full atlas texture size matches the region size (or larger),
  // we compute UV scale & offset based on normalized coordinates.
  // Since the region starts at (0,0) we only need to scale.
  const uvScale = new Vector2(1 / (regionWidth / regionWidth), 1 / (regionHeight / regionHeight)); // identity
  // In case the atlas is larger, you could compute real scale here.
  // Here we simply keep default UVs because the region occupies the full texture.

  const material = new ctx.THREE.MeshBasicNodeMaterial();
  material.transparent = true;

  // Load texture asynchronously; the node must be returned synchronously.
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      // Connect the texture to the material via a node.
      material.mapNode = texture(tex);
      // Force material update.
      material.needsUpdate = true;
    });
  }

  const plane = new THREEMesh(geometry, material);
  // Ensure the plane always faces the camera (simple billboarding).
  plane.onBeforeRender = (renderer, scene, camera) => {
    plane.quaternion.copy(camera.quaternion);
  };
  root.add(plane);

  // ---- No cinematic primitives to apply for this node ----
  // Store any resources that need explicit disposal.
  const disposables = {
    geometry,
    material,
    texture: () => loadedTexture && loadedTexture.dispose(),
  };

  // ---- Cleanup --------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose geometry and material.
    disposables.geometry.dispose();
    disposables.material.dispose();
    disposables.texture();

    // Kill any GSAP timelines that might have been created (none here, but safe).
    gsap.globalTimeline.clear();
  };

  // ---- Event handlers placeholder --------------------------------
  root.userData.handlers = {};

  return root;
}
